/* Auto-generated by update-homepage-feed.py. Do not edit manually. */
const homepageItems = [];
(function () {
  const grid = document.getElementById('home-highlights-grid');
  if (!grid) return;
  const items = homepageItems.slice();
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  const selected = items.slice(0, 4);
  grid.replaceChildren();
  if (!selected.length) {
    const empty = document.createElement('p');
    empty.className = 'home-highlights-empty';
    empty.textContent = 'New reflections and podcast episodes will appear here as they are published. Explore the blog and podcast sections in the meantime.';
    grid.appendChild(empty);
    return;
  }
  selected.forEach(item => {
    const card = document.createElement('article'); card.className='home-highlight-card';
    const type=document.createElement('span'); type.className='highlight-type'; type.textContent=item.type;
    const heading=document.createElement('h3'); const link=document.createElement('a'); link.href=item.url; link.textContent=item.title; heading.appendChild(link);
    const desc=document.createElement('p'); desc.textContent=item.description;
    card.append(type,heading,desc);
    if(item.date){ const meta=document.createElement('span'); meta.className='highlight-meta'; meta.textContent=item.date; card.appendChild(meta); }
    const more=document.createElement('a'); more.className='highlight-read'; more.href=item.url; more.textContent=item.type==='Podcast'?'Listen / View →':'Read more →'; card.appendChild(more);
    grid.appendChild(card);
  });
})();
